INSERT INTO `categorias` VALUES (1,'SIN CATEGORIA','Productos aún sin clasificar en una categoría específica; conviene asignarles la que corresponda.',1,'2026-11-03 19:49:31','2026-11-21 02:37:05'),(2,'BOTELLA','Productos líquidos en botella o frasco grande: alcohol, agua oxigenada, jabones líquidos y antisépticos de uso diario.',1,'2026-11-03 19:49:32','2026-11-21 02:37:05'),(3,'CREMA TOPICO','Crema de uso tópico (sobre la piel): corticoides, antimicóticos y antibióticos dermatológicos en concentraciones bajas.',1,'2026-11-03 19:49:32','2026-11-21 02:37:05'),(4,'POMADA','Preparación grasa y espesa para la piel: analgésicos, calentadores musculares y antiinflamatorios tópicos.',1,'2026-11-03 19:49:32','2026-11-21 02:37:05'),(5,'CREMA VAGINAL','Crema para aplicación vaginal con aplicador, usada para infecciones como la candidiasis (clotrimazol).',1,'2026-11-03 19:49:32','2026-11-21 02:37:05'),(6,'CAPSULA','Cápsula dura de gelatina que contiene el medicamento en polvo o gránulos; se traga entera con agua.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(7,'PARCHE','Parches adhesivos que se pegan sobre la piel para aliviar dolores musculares o articulares.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(8,'COMPRIMIDO','Forma sólida de dosis exacta que se traga con agua; la presentación más común de analgésicos, antibióticos y otros.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(9,'GOTAS','Medicamentos líquidos que se dosifican por gotas: orales para niños (paracetamol, antiespasmódicos) u oftálmicos.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(10,'CREMA','Preparación semisólida para aplicar sobre la piel: antivirales, antimicóticos, cicatrizantes y dermatológicos.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(11,'SOBRE','Medicamento en sobre de una dosis (polvo o granulado) que se disuelve en agua: antigripales, mucolíticos, sales.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(12,'TABLETA','Forma sólida para tragar de dosis exacta (como el comprimido): analgésicos, antivirales, antibióticos y más.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(13,'ANTIBIOTICO','Medicamentos que eliminan o frenan bacterias. Requieren receta médica y deben tomarse el tratamiento completo.',1,'2026-11-03 19:49:33','2026-11-21 02:37:05'),(14,'SUPOSITORI REXTAL','Supositorios para aplicar por vía rectal, como la glicerina para el estreñimiento en niños.',1,'2026-11-03 19:49:34','2026-11-21 02:37:05'),(15,'JABON','Jabones de uso dermatológico o artesanal, como el jabón de azufre para piel grasa, acné u hongos.',1,'2026-11-03 19:49:34','2026-11-21 02:37:05'),(16,'MAMADERA CON SENSOR DE TEMPERATURA','Mamadera con sensor que cambia de color para indicar si la leche está demasiado caliente para el bebé.',1,'2026-11-03 19:49:34','2026-11-21 02:37:05'),(17,'SOBRES','Sobres de una dosis para disolver en agua: antigripales, protectores gástricos y probióticos. Igual a la categoría SOBRE.',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(18,'PASTILLA','Pastillas para chupar (disolver en la boca), como las de la garganta o para la tos.',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(19,'UNGUENTO','Ungüento: preparación grasa y espesa para la piel o las vías respiratorias, como el Mentisan o los antihemorroidales.',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(20,'JARABE','Medicamento líquido oral, generalmente endulzado: antitusivos, mucolíticos, analgésicos y vitaminas, sobre todo para niños.',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(21,'AMPOLLA INYECTABLE','Ampolla o vial para aplicar por inyección (intramuscular o intravenosa); incluye polvos para reconstituir y agua destilada.',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(22,'PAÑAL','Pañales desechables para bebé, por talla según el peso (P, M, G, XG).',1,'2026-11-03 19:49:35','2026-11-21 02:37:05'),(23,'PAÑAL ADULTO','Pañales desechables para adultos con incontinencia, por talla según el peso o la cintura.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(24,'CAPSULAS BLANDAS','Cápsula blanda (perla) de gelatina con contenido líquido u oleoso: vitaminas, omega, analgésicos de rápida absorción.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(25,'OVULOS','Óvulos vaginales: forma sólida que se introduce en la vagina para tratar infecciones (clotrimazol, metronidazol).',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(26,'SUSPENSION','Líquido oral con partículas en suspensión: se agita antes de usar. Común en antibióticos y antiparasitarios pediátricos.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(27,'TABLETAS MASTICABLES','Tabletas para masticar antes de tragar, como antiácidos y protectores gástricos (subsalicilato de bismuto).',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(28,'CAPSULAS','Cápsulas duras, a menudo en frasco: antibióticos, suplementos y antigripales. Misma forma que la categoría CAPSULA.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(29,'POLVO','Medicamento en polvo, para reconstituir (antibióticos inyectables o suspensiones) o disolver al tomarlo.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(30,'COLECTOR DE HECES','Frasco estéril con tapa para recoger una muestra de heces para análisis de laboratorio.',1,'2026-11-03 19:49:36','2026-11-21 02:37:05'),(31,'COMPRIMIDO SUDBLINGUAL','Comprimido que se disuelve debajo de la lengua para un efecto más rápido (ketorolaco). Igual a COMPRIMIDO SUBLINGUAL.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(32,'EQUIPO DE SUERO','Equipo de venoclisis para pasar sueros y soluciones por vía intravenosa, con regulador de goteo.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(33,'VITAMINA C','Suplementos de vitamina C (ácido ascórbico) para reforzar las defensas y prevenir resfriados.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(34,'COMPRIMIDO SUBLINGUAL','Comprimido que se disuelve debajo de la lengua para un efecto más rápido, como el ketorolaco sublingual.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(35,'TABLETA EFERVESENTE','Tableta que se disuelve en agua formando burbujas: vitamina C, antiácidos y suplementos de calcio y magnesio.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(36,'VITAMINAS OFTALMICAS','Suplementos vitamínicos para la salud visual (luteína, zeaxantina, antioxidantes), en cápsulas.',1,'2026-11-03 19:49:37','2026-11-21 02:37:05'),(37,'GRANULADO','Medicamento en gránulos para disolver en agua o tomar directamente, como paracetamol granulado o protectores hepáticos.',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(38,'AEROSOL','Medicamento en envase presurizado que libera dosis medidas al inhalar, como el salbutamol para el asma y el broncoespasmo.',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(39,'SUSPENCION','Suspensión oral (polvo o líquido que se agita antes de usar), como antiparasitarios. Igual a la categoría SUSPENSION.',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(40,'LAXANTE','Productos para el estreñimiento: laxantes orales (bisacodilo, picosulfato) y rectales como la glicerina.',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(41,'AMPOLLA','Envase de vidrio o plástico cerrado con una dosis líquida; puede ser inyectable o bebible (p. ej. Enterogermina).',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(42,'COLECTOR DE ORINA','Frasco estéril para recoger una muestra de orina para análisis de laboratorio (examen general, urocultivo).',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(43,'SOLUCION PARA PERFUSION','Solución estéril para administrar por vía intravenosa gota a gota (infusión), como el paracetamol inyectable.',1,'2026-11-03 19:49:38','2026-11-21 02:37:05'),(44,'SPRAY','Medicamento en spray para aplicar sobre la piel o heridas: antiinflamatorios, antibióticos tópicos y antimicóticos.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(45,'JERINGA','Jeringas descartables para inyectar o medir líquidos, en distintas capacidades (ml).',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(46,'LAGRIMAS ARTIFICIALES','Gotas lubricantes para ojos secos o irritados por pantallas, viento o lentes de contacto.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(47,'SOLUCION','Medicamentos líquidos en solución: orales (lactulosa), tópicos (lociones) o para infusión intravenosa (Ringer).',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(48,'GEL','Preparación en gel transparente: antiinflamatorios tópicos (diclofenaco), geles íntimos y otros de fácil absorción.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(49,'GLUCOSA','Solución intravenosa de glucosa (dextrosa) al 5 % para hidratación y aporte de energía; uso con indicación médica.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(50,'SUERO FISIOLOGICO','Solución de cloruro de sodio al 0,9 % para hidratación intravenosa, lavado de heridas y limpieza nasal.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(51,'SOLUCION ANASTESICA','Solución con anestésico local para calmar el dolor de encías, boca o garganta (p. ej. por la dentición).',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(52,'GOTAS OFTALMICAS','Gotas estériles para los ojos: antibióticas, lubricantes (lágrimas artificiales) y descongestionantes.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(53,'PEZON','Pezoneras y chupones de repuesto para mamaderas, por tamaño o flujo (pequeño, mediano, grande).',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(54,'ASPIRADOR','Aspirador nasal para bebés y niños: retira la mucosidad cuando están resfriados y aún no saben sonarse.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(55,'CABESTRILLO','Cabestrillo o inmovilizador de brazo para sostener el hombro, codo o muñeca tras golpes, esguinces o fracturas.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(56,'MAMADERA','Mamaderas (biberones) para la alimentación del bebé, en distintas capacidades y tipos de chupón.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(57,'MARIPOSA','Aguja tipo mariposa (scalp) con alas para canalizar venas pequeñas o tomar muestras de sangre; el número indica el calibre.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(58,'TAMPONES','Tampones de higiene femenina, por nivel de flujo (medio, súper).',1,'2026-11-03 19:49:39','2026-11-21 02:37:05'),(59,'TERMOMETRO DIGITAL','Termómetro digital para medir la temperatura corporal por vía oral, axilar o rectal.',1,'2026-11-03 19:49:39','2026-11-21 02:37:05');
/*!40000 ALTER TABLE `categorias` ENABLE KEYS */;
