INSERT INTO `laboratorios` VALUES (1,'REMUS+','LABORATORIO','Línea Remus+: cremas y geles de uso tópico, como clotrimazol vaginal y diclofenaco en gel (Diclus B Forte) (sin datos verificados)',1,'2026-11-03 19:49:32','2026-11-21 02:34:48'),(2,'CURE BAND','MARCA','Cure Band, marca de insumos de curación (esparadrapo, micropore, curitas, gasas) comercializada en Colombia y la región; aquí: micropore piel.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(4,'ALCOS','LABORATORIO','Grupo Alcos S.A., laboratorio farmacéutico boliviano con sede en La Paz (desde 1971), miembro de CIFABOL; línea Alco: Alcofen, Alcoderm, Al-Codion, Alcolax.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(5,'IMEG','LABORATORIO','Laboratorio que distribuye en Bolivia analgésicos antirreumáticos (Algidol Reuma Forte) y antibióticos tópicos en spray (rifamicina) (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(6,'SAVANT','LABORATORIO','Savant Pharm, laboratorio argentino con presencia en Bolivia; su línea Savant Consumer incluye Almaximo (sildenafil).',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(7,'MAVE','LABORATORIO','Probablemente Laboratorios Maver (Chile), escrito distinto; su producto Armonyl Noche es un auxiliar para conciliar el sueño, de venta libre.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(8,'QUIMFA','LABORATORIO','Laboratorio de analgésicos y antiinflamatorios (Profenol, Dolonet, Dolanet), además de pregabalina (Prebalin) y bisoprolol (Bisol) (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(10,'ALMOS','LABORATORIO','Laboratorios Almos S.A., industria químico-farmacéutica de Paraguay (planta en Ypané); aquí distribuye Dolo Reumin, analgésico antiinflamatorio y antirreumático.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(11,'LCH','LABORATORIO','Laboratorio Chile (LCH), farmacéutica chilena con sede en Santiago y unos 700 productos, gran productor de genéricos; analgésicos (Dolo-Octirona), corticoides y antidepresivos.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(12,'LASCA','LABORATORIO','Laboratorios Lasca, farmacéutica paraguaya con casi 90 años de trayectoria y exportaciones a Bolivia; analgésicos (Dolostop), biotecnológicos e inyectables.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(13,'BAGO','LABORATORIO','Laboratorios Bagó, grupo farmacéutico argentino con filial y planta propia en Bolivia (Bagó de Bolivia, La Paz); marcas como Refrianex, Migranol, Ulcozol y Pen Di Ben.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(15,'TECNOFARMA','LABORATORIO','Tecnofarma, empresa farmacéutica regional con operación en Perú y Bolivia (importadora y distribuidora); analgésicos (Tialgin), vitaminas B y suplementos.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(16,'INDUFAR','LABORATORIO','Indufar, laboratorio farmacéutico paraguayo con más de 50 años, exporta a Bolivia; líneas de analgésicos (Zmol), antiespasmódicos, oftálmicos, dermatológicos y respiratorios.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(17,'LA SANTE','LABORATORIO','Laboratorios La Santé, farmacéutica colombiana nacida en Bogotá en 1989, presente en 13 países de Latinoamérica; genéricos y marcas, como zopiclona para el insomnio.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(18,'SAE','LABORATORIO','Laboratorio de genéricos y marcas propias: analgésicos (diclofenaco, Golpex gel), hipnóticos (zopiclona), gotas oftálmicas y cremas antivirales (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(20,'TERBOL','LABORATORIO','Terbol (Terapéutica Boliviana S.A.), laboratorio boliviano de Santa Cruz, miembro de Cifabol; genéricos y marcas como Ibupronal, Isoton-C, 4Derm y Vagizol.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(22,'MAVER','LABORATORIO','Laboratorios Maver, farmacéutico chileno fundado en 1923 (Santiago), centrado en productos de venta libre; llega a Bolivia por distribuidores (Armonyl, Viosinal).',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(23,'VALENCIA','LABORATORIO','Laboratorios Valencia (Grupo Empresarial Valencia), boliviano, fundado en 1977; productos naturales de medicina andina, como Arocarbol (hepático y digestivo).',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(24,'TELCHI','LABORATORIO','Proveedor de insumos farmacéuticos básicos en sobre: azufre, bicarbonato de sodio y sulfato de magnesio (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(25,'UNIVERSAL PHARMA','LABORATORIO','Universal Pharma, empresa boliviana de Santa Cruz (desde 2002); distribuye genéricos con marca propia fabricados en India: antibióticos, analgésicos y vitaminas.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(26,'INTI','LABORATORIO','Droguería INTI, laboratorio boliviano fundado en 1936 (planta en El Alto, La Paz), creador del ungüento Mentisan; más de 1.200 productos propios y representados.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(27,'MHEDICAL PHARMA','LABORATORIO','Laboratorio que distribuye en Bolivia anticonvulsivos, inyectables para infusión y pruebas rápidas de embarazo (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(28,'LAQFAGAL','LABORATORIO','Laqfagal, laboratorio farmacéutico boliviano miembro de Cifabol; produce genéricos y marcas propias: cardiovasculares, antibióticos urinarios, corticoides inyectables y mucolíticos.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(29,'PORTUGAL','LABORATORIO','Laboratorios Portugal, farmacéutica peruana de Arequipa fundada en 1864, gran exportadora; genéricos y marcas como Clavutrim, Multi Frost y Desazona.',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(30,'GARDEN HOUSE','LABORATORIO','Laboratorios Garden House Farmacéutica, laboratorio chileno (San Bernardo, Santiago) conocido por la línea de laxantes naturales Ciruelax (comprimidos y jalea).',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(31,'KRISPAR','LABORATORIO','Laboratorio que distribuye en Bolivia genéricos de antibióticos (claritromicina) y cardiovasculares (carvedilol) (sin datos verificados)',1,'2026-11-03 19:49:33','2026-11-21 02:34:48'),(32,'DELTA','LABORATORIO','Laboratorio Químico Farmacéutico Industrial Delta S.A., laboratorio boliviano miembro de CIFABOL con más de 30 años; genéricos: paracetamol, antibióticos, antiparasitarios.',1,'2026-11-03 19:49:34','2026-11-21 02:34:48'),(34,'IFA','LABORATORIO','Laboratorio farmacéutico boliviano con sede en Santa Cruz de la Sierra (fundado en 1988), miembro de Cifabol; fabrica genéricos: antibióticos, diuréticos, inyectables y cremas.',1,'2026-11-03 19:49:34','2026-11-21 02:34:48'),(35,'PHARMACARE','LABORATORIO','Laboratorio que distribuye genéricos y marcas propias: analgésicos (Dolocalma, ibuprofeno), antibióticos y cremas dermatológicas combinadas (sin datos verificados)',1,'2026-11-03 19:49:34','2026-11-21 02:34:48'),(36,'GUAYAKJ','LABORATORIO','Guayakí S.A. (Laboratorios IMEG), laboratorio farmacéutico paraguayo de Asunción, proveedor del Ministerio de Salud de Paraguay; aquí: ivermectina 6 mg comprimidos.',1,'2026-11-03 19:49:34','2026-11-21 02:34:48'),(42,'MAMI','MARCA','Marca de pañales desechables para bebé vendida en Bolivia, en tallas G y XG (sin datos verificados)',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(43,'NENESOFT','MARCA','Marca de pañales desechables para bebé vendida en Bolivia, incluida la talla P para recién nacidos (sin datos verificados)',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(44,'SENSATY','MARCA','Marca de pañales y productos de incontinencia para adultos, en tallas G y EG (sin datos verificados)',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(46,'BAYER','LABORATORIO','Bayer, multinacional farmacéutica alemana (Leverkusen); línea de consumo conocida: Aspirinetas, Alka-Seltzer y Actron (ibuprofeno) para dolor y fiebre.',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(47,'BQS - PHARMA','LABORATORIO','Laboratorio o distribuidora de genéricos en Bolivia: antibióticos como amoxicilina + ácido clavulánico y analgésicos como ibuprofeno 600 mg (sin datos verificados)',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(49,'SANAT','LABORATORIO','Sanat Pharma S.R.L., farmacéutica boliviana (Cochabamba); genéricos y marcas propias: antibióticos, antihistamínicos, estatinas y para disfunción eréctil.',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(51,'LAFAR','LABORATORIO','Laboratorios Lafar, farmacéutico boliviano con sede en La Paz (1988), miembro de Cifabol; fuerte en pediatría, gastroenterología y dermatología (Typirec, Antiflat, lactulosa).',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(53,'ABBOTT','LABORATORIO','Multinacional farmacéutica estadounidense (Illinois, EE. UU.), con amplia línea de medicamentos, nutrición y diagnóstico; aquí: Bacterol Forte (sulfametoxazol + trimetoprima).',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(55,'MEGALABS','LABORATORIO','Megalabs, grupo farmacéutico latinoamericano de origen uruguayo, con oficinas en Santa Cruz, La Paz y Cochabamba; marcas como Sertal, Bismutip, Flogiatrin y Viadil.',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(57,'REMUS','LABORATORIO','Laboratorio que provee antibióticos inyectables como cefotaxima 1 g en polvo para uso hospitalario y ambulatorio (sin datos verificados)',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(58,'BRESKOT','LABORATORIO','Breskot Pharma, marca farmacéutica presente en el vademécum boliviano; analgésicos, antiinflamatorios y vitaminas B: Cofargot, Flexicam B12, Espasmo Loxadin.',1,'2026-11-03 19:49:36','2026-11-21 02:34:48'),(61,'INQUIBOL','LABORATORIO','Laboratorio que distribuye en Bolivia genéricos, en especial antibióticos orales como dicloxacilina (sin datos verificados)',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(63,'FARMEDICAL','LABORATORIO','Farmedical S.R.L., empresa farmacéutica boliviana con sede en La Paz (fundada en 2015), importa y comercializa medicamentos; aquí: Dipin 20 mg (nifedipino).',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(65,'UNICURE','LABORATORIO','Unicure Remedies, laboratorio de India (Vadodara, Gujarat) fundado en 1979, con certificación OMS-GMP; exporta genéricos: N-acetilcisteína, ibuprofeno y antimicóticos.',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(67,'APOTEX','LABORATORIO','Apotex, farmacéutica canadiense (Toronto) especializada en medicamentos genéricos con prefijo APO; aquí: Apo Gravol (dimenhidrinato) para mareo y náuseas.',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(68,'BIOVIGOR','LABORATORIO','Marca de suplementos o productos naturales; en la farmacia vende Hepatomix 500 mg en cápsulas, protector hepático (sin datos verificados)',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(69,'INDOCO','LABORATORIO','Indoco Remedies, farmacéutica de la India con sede en Mumbai; fabrica formulaciones y principios activos que exporta a más de 50 países, incluidos analgésicos como Ibuflamar.',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(70,'GALENMARS','LABORATORIO','Laboratorio de genéricos y marcas propias: Ibugalen (ibuprofeno 600/800 mg), Tobradex oftálmico, diclofenaco gel y ceftriaxona inyectable (sin datos verificados)',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(73,'COFAR','LABORATORIO','Laboratorios COFAR S.A., laboratorio farmacéutico boliviano con sede en La Paz y miembro de CIFABOL; amplia línea de genéricos, inyectables, jarabes y gotas.',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(74,'VIVE','LABORATORIO','Laboratorio de antiinflamatorios como meloxicam 15 mg (Loxi) (sin datos verificados)',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(77,'DISMEDIN','LABORATORIO','Laboratorio que en la farmacia provee nifedipino 10 mg en comprimidos, antihipertensivo genérico (sin datos verificados)',1,'2026-11-03 19:49:37','2026-11-21 02:34:48'),(79,'NOVOPHARMA','LABORATORIO','Laboratorio que distribuye en Bolivia medicamentos inyectables: antibióticos (Novopencil), protectores gástricos y antieméticos (sin datos verificados)',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(83,'ROWA','LABORATORIO','Rowa Pharmaceuticals, laboratorio de Irlanda (Bantry, Cork); fitofármacos de aceites esenciales: Rowachol (cálculos biliares) y Rowatinex (cálculos renales).',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(85,'MEFORT','LABORATORIO','Marca de suplementos nutricionales que se vende en farmacias de Bolivia, como vitamina K2 en cápsulas (sin datos verificados)',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(87,'TORRICO','LABORATORIO','Proveedor de jarabes de venta libre como Actimol 60 ml (sin datos verificados)',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(90,'FABRA','LABORATORIO','Laboratorios Fabra, laboratorio farmacéutico argentino (Buenos Aires); aquí: Butasona Fabra, corticoide inyectable a base de betametasona.',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(91,'PFIZER','LABORATORIO','Pfizer, multinacional farmacéutica de EE. UU. (Nueva York); medicamentos de marca e innovadores, entre ellos el anticonceptivo inyectable Depo-Provera.',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(93,'FARMA FINA','LABORATORIO','Laboratorio que provee Febris Forte en solución para perfusión de 100 ml, antipirético/analgésico inyectable de uso hospitalario (sin datos verificados)',1,'2026-11-03 19:49:38','2026-11-21 02:34:48'),(94,'ABD','LABORATORIO','Laboratorios ABD Ltda., empresa farmacéutica boliviana; en la farmacia aporta inyectables genéricos como ketorolaco en ampolla y fluconazol en solución inyectable.',1,'2026-11-03 19:49:39','2026-11-21 02:34:48'),(101,'VITA','LABORATORIO','Laboratorios Vita S.A., farmacéutica boliviana fundada en 1936; medicamentos, suplementos, tónicos y cosméticos (Tónico Vita, Enema Vit, Carla Lorena).',1,'2026-11-03 19:49:39','2026-11-21 02:34:48'),(104,'MAIC','MARCA','Marca de artículos para bebé, como mamaderas y accesorios de alimentación infantil (sin datos verificados)',1,'2026-11-03 19:49:39','2026-11-21 02:34:48'),(105,'BEBESITOS','MARCA','Marca de artículos para bebé como mamaderas (biberones) de 12 oz (sin datos verificados)',1,'2026-11-03 19:49:39','2026-11-21 02:34:48'),(107,'P&G','LABORATORIO','Procter & Gamble (EE. UU.), multinacional de consumo; desde 2018 tiene la línea de salud de Merck KGaA, con marcas como Neurobion y Dolo-Neurobion.',1,'2026-11-03 19:49:40','2026-11-21 02:34:48'),(110,'TERMAL','LABORATORIO','Productor de jabones artesanales, como jabón de azufre neutro para el cuidado de la piel (sin datos verificados)',1,'2026-11-06 02:40:30','2026-11-21 02:34:48'),(111,'ANARA','LABORATORIO','Anara es marca de laxante estimulante a base de picosulfato de sodio 5 mg, registrada en México por Laboratorios Chinoin; se usa para estreñimiento ocasional.',1,'2026-11-07 02:32:23','2026-11-21 02:34:48'),(112,'IFARBO','LABORATORIO','Industria Farmacéutica Boliviana (Ifarbo Ltda.), laboratorio nacional miembro de Cifabol; elabora medicamentos de uso común y antisépticos como violeta de genciana.',1,'2026-11-07 02:49:21','2026-11-21 02:34:48'),(114,'ENGELHARD','LABORATORIO','Engelhard Arzneimittel, laboratorio alemán especializado en fitofármacos; su producto estrella es Abrilar, jarabe de extracto de hoja de hiedra para la tos con flema.',1,'2026-11-07 23:21:16','2026-11-21 02:34:48'),(115,'DUTRIEC','LABORATORIO','Dutriec S.A., laboratorio farmacéutico paraguayo (Asunción), proveedor del Ministerio de Salud de Paraguay; analgésicos como dipirona (metamizol) en ampolla y comprimidos.',1,'2026-11-10 01:18:13','2026-11-21 02:34:48'),(116,'ROHANA','LABORATORIO','Marca de productos de higiene y cuidado capilar, como shampoo antipiojos de 300 ml (sin datos verificados)',1,'2026-11-11 01:30:03','2026-11-21 02:34:48'),(117,'MINERVA','LABORATORIO','Laboratorios Minerva, farmacéutico boliviano miembro de Cifabol; fabrica jarabes, gotas y suspensiones pediátricas (Acetamin, Broxomin) y genéricos.',1,'2026-11-11 01:31:39','2026-11-21 02:34:48'),(118,'NEOJECT','LABORATORIO','Marca de insumos médicos descartables, como agujas hipodérmicas y jeringas (sin datos verificados)',1,'2026-11-11 02:22:57','2026-11-21 02:34:48'),(119,'OPES HEALTHCARE','LABORATORIO','Opes Healthcare Pvt. Ltd., fabricante farmacéutico de India (Ahmedabad, Gujarat), fundado en 2018; produce tabletas, jarabes e inyectables como ketorolaco.',1,'2026-11-11 02:28:23','2026-11-21 02:34:48'),(120,'BABU','MARCA','Marca de pañales desechables para bebé (tallas por peso, p. ej. P de 3 a 6 kg) (sin datos verificados)',1,'2026-11-18 01:01:25','2026-11-21 02:34:48'),(121,'MINTLAB','LABORATORIO','Mintlab Co. S.A., laboratorio chileno de genéricos con sede en Santiago (Independencia); comprimidos como alopurinol, atorvastatina y prednisona.',1,'2026-11-18 01:01:25','2026-11-21 02:34:48'),(122,'UMEDICA','LABORATORIO','Umedica Laboratories, farmacéutica de India (Vapi, Gujarat) fundada en 1982, con certificación OMS-GMP y exporta a más de 35 países; genéricos como omeprazol (Omebi).',1,'2026-11-21 02:20:12','2026-11-21 02:34:48');
