INSERT INTO `presentaciones` VALUES (1,'%','Porcentaje (%): concentración del principio activo en cremas, soluciones y antisépticos (p. ej. agua oxigenada 3 %, alcohol 70 %).',NULL,1,'2026-11-03 19:49:31','2026-11-21 02:42:23'),(2,'CAPSULA','Cápsula: unidad sólida de gelatina con el medicamento dentro; se vende y se dosifica por cápsula.',NULL,1,'2026-11-03 19:49:33','2026-11-21 02:42:23'),(3,'CM','Centímetros (cm): medida de largo o ancho de insumos de curación, como gasas, micropore y esparadrapo.',NULL,1,'2026-11-03 19:49:33','2026-11-21 02:42:23'),(4,'COMPRIMIDO','Comprimido: unidad sólida de dosis exacta; se vende por comprimido suelto o por blíster.',NULL,1,'2026-11-03 19:49:33','2026-11-21 02:42:23'),(5,'GOTAS','Gotas: medicamento líquido que se dosifica gota a gota (orales u oftálmicos); el envase indica los ml.',NULL,1,'2026-11-03 19:49:33','2026-11-21 02:42:23'),(6,'GR','Gramos (g): peso o contenido del producto, usado en cremas, pomadas, geles, polvos y algodón.',NULL,1,'2026-11-03 19:49:33','2026-11-21 02:42:23'),(7,'GRAMO','Gramos (g): peso o contenido del producto (cremas, ungüentos, pastillas). Equivale a la presentación GR.',NULL,1,'2026-11-03 19:49:35','2026-11-21 02:42:23'),(8,'INYECTABLE','Inyectable: ampolla o vial para aplicar por vía intramuscular o intravenosa; se vende por unidad.',NULL,1,'2026-11-03 19:49:35','2026-11-21 02:42:23'),(9,'KG','Kilogramos (kg): rango de peso de la persona para el que está hecho el producto, como las tallas de pañales.',NULL,1,'2026-11-03 19:49:35','2026-11-21 02:42:23'),(10,'MG','Miligramos (mg): cantidad de principio activo por unidad (comprimido, cápsula, sobre), p. ej. paracetamol 500 mg.',NULL,1,'2026-11-03 19:49:36','2026-11-21 02:42:23'),(11,'ML','Mililitros (ml): volumen de líquidos como jarabes, suspensiones, gotas, ampollas y soluciones.',NULL,1,'2026-11-03 19:49:38','2026-11-21 02:42:23'),(12,'PASTILLA','Pastilla: unidad para chupar o disolver en la boca, como las pastillas para la garganta o la tos.',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(13,'PEZON','Pezón o chupón de repuesto para mamadera; se vende por unidad y por tamaño.',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(14,'PIEZA','Pieza: se vende por unidad entera; para insumos y artículos (mamaderas, aspiradores, mariposas, termómetros).',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(15,'SOBRE','Sobre: dosis individual en polvo o granulado para disolver en agua; se vende por sobre.',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(16,'SPRAY','Spray: envase con atomizador para aplicar el producto sobre la piel o heridas; se vende por frasco.',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(17,'TABLETA','Tableta: unidad sólida para tragar de dosis exacta (como el comprimido); se vende suelta o por blíster.',NULL,1,'2026-11-03 19:49:39','2026-11-21 02:42:23'),(18,'U.I','Unidades Internacionales (UI): medida de actividad usada en vitaminas (A, D, E), hormonas y algunos antibióticos. Igual a UI.',NULL,1,'2026-11-03 19:49:40','2026-11-21 02:42:23'),(19,'UI','Unidades Internacionales (UI): medida de actividad usada en vitaminas, hormonas y antimicóticos como la nistatina.',NULL,1,'2026-11-03 19:49:40','2026-11-21 02:42:23');
/*!40000 ALTER TABLE `presentaciones` ENABLE KEYS */;
UNLOCK TABLES;

